def replace_exact(path, old_str, new_str)
  content = File.read(path)
  raise "Pattern not found in #{path}:\n#{old_str}" unless content.include?(old_str)
  raise "Pattern found multiple times in #{path}:\n#{old_str}" if content.scan(old_str).size > 1
  File.write(path, content.sub(old_str, new_str))
end

